questionvariables.text:
/* Type 2 reducible equation: a quadratic in sin(theta) or cos(theta), 0 <= theta <= 360.
   Designed backwards from the roots: 11 root pairs x {sin, cos} = 22 distinct variants.
   Roots +-2 have no solution (they test -1 <= sin, cos <= 1). */
rpool : [[0, 1/2], [0, -1/2], [0, 1], [1/2, 1], [-1/2, 1], [1/2, -1], [-1/2, -1], [1/2, 2], [-1/2, 2], [1/2, -2], [-1/2, -2]];
rr : rand(rpool);
r1 : rr[1];
r2 : rr[2];
fs : rand([1, 2]);            /* 1 = sine, 2 = cosine */
trg : if fs = 1 then sin(theta) else cos(theta);

/* quadratic in x = sin(theta) or cos(theta) */
f1 : if r1 = 0 then x else denom(r1)*x - num(r1);
f2 : if r2 = 0 then x else denom(r2)*x - num(r2);
pfac : f1*f2;                 /* model factorised form, e.g. (2*x-1)*(x+1) */
pexp : expand(pfac);
eqn : subst(trg, x, pexp) = 0;
rts : [r1, r2];
nval : if abs(r2) > 1 then 1 else 2;   /* number of roots that give angles */

/* solutions of trig(theta) = r for each root (exact table, 0..360 inclusive) */
s1 : if fs = 1 then (if r1 = 0 then [0,180,360] else (if r1 = 1/2 then [30,150] else (if r1 = -1/2 then [210,330] else (if r1 = 1 then [90] else (if r1 = -1 then [270] else ([])))))) else (if r1 = 0 then [90,270] else (if r1 = 1/2 then [60,300] else (if r1 = -1/2 then [120,240] else (if r1 = 1 then [0,360] else (if r1 = -1 then [180] else ([]))))));
s2 : if fs = 1 then (if r2 = 0 then [0,180,360] else (if r2 = 1/2 then [30,150] else (if r2 = -1/2 then [210,330] else (if r2 = 1 then [90] else (if r2 = -1 then [270] else ([])))))) else (if r2 = 0 then [90,270] else (if r2 = 1/2 then [60,300] else (if r2 = -1/2 then [120,240] else (if r2 = 1 then [0,360] else (if r2 = -1 then [180] else ([]))))));
sall : sort(append(s1, s2));
/* common slip: roots with the wrong signs */
w1 : if fs = 1 then (if -r1 = 0 then [0,180,360] else (if -r1 = 1/2 then [30,150] else (if -r1 = -1/2 then [210,330] else (if -r1 = 1 then [90] else (if -r1 = -1 then [270] else ([])))))) else (if -r1 = 0 then [90,270] else (if -r1 = 1/2 then [60,300] else (if -r1 = -1/2 then [120,240] else (if -r1 = 1 then [0,360] else (if -r1 = -1 then [180] else ([]))))));
w2 : if fs = 1 then (if -r2 = 0 then [0,180,360] else (if -r2 = 1/2 then [30,150] else (if -r2 = -1/2 then [210,330] else (if -r2 = 1 then [90] else (if -r2 = -1 then [270] else ([])))))) else (if -r2 = 0 then [90,270] else (if -r2 = 1/2 then [60,300] else (if -r2 = -1/2 then [120,240] else (if -r2 = 1 then [0,360] else (if -r2 = -1 then [180] else ([]))))));
wall : sort(append(w1, w2));
/* common slip: leaving out 0 and/or 360 */
noends : sort(listify(setdifference(setify(sall), {0, 360})));
nsall : float(sall);
nwall : float(wall);
nnoends : float(noends);
ns1 : float(s1);
ns2 : float(s2);
nsr : float(sort(rts));
nsrw : float(sort(-rts));

feedbackvariables.text:
/* the student's values as a sorted list of numbers (a list or a set is accepted, in any order) */
sl : if listp(ans2) then ans2 else if setp(ans2) then listify(ans2) else [ans2];
L : float(sort(sl));
okr : if length(L) = length(nsr) and length(nsr) > 0 then is(lmax(abs(L - nsr)) <= 0.01) else false;
wr : if length(L) = length(nsrw) and length(nsrw) > 0 then is(lmax(abs(L - nsrw)) <= 0.01) else false;

/* the student's values as a sorted list of numbers (a list or a set is accepted, in any order) */
sl : if listp(ans3) then ans3 else if setp(ans3) then listify(ans3) else [ans3];
L : float(sort(sl));
okt : if length(L) = length(nsall) and length(nsall) > 0 then is(lmax(abs(L - nsall)) <= 0.01) else false;
ne : if length(L) = length(nnoends) and length(nnoends) > 0 then is(lmax(abs(L - nnoends)) <= 0.01) else false;
o1 : if length(L) = length(ns1) and length(ns1) > 0 then is(lmax(abs(L - ns1)) <= 0.01) else false;
o2 : if length(L) = length(ns2) and length(ns2) > 0 then is(lmax(abs(L - ns2)) <= 0.01) else false;
wt : if length(L) = length(nwall) and length(nwall) > 0 then is(lmax(abs(L - nwall)) <= 0.01) else false;
oneonly : is(nval = 2 and (o1 or o2));
